for t in range(int(input())):
	(n, m) = list(map(int, input().split()))
	f = list(map(int, input().split()))
	c = list(map(int, input().split()))
	k = 0
	a = 0
	p = 1
	l = 1
	while n != k and m != a:
		if f[k] < c[a]:
			if p == 0:
				l += 1
			k += 1
			p = 1
		else:
			if p:
				l += 1
			a += 1
			p = 0
	print(l)
